"""Rotas de tutores."""

from fastapi import APIRouter, Response, status

from vetclinic.routers import ConnectionDependency
from vetclinic.schemas.faturas import InvoiceOutput
from vetclinic.schemas.pets import PetOutput
from vetclinic.schemas.tutores import TutorInput, TutorOutput
from vetclinic.services import tutores as tutor_service

router = APIRouter(prefix="/tutores", tags=["tutores"])


@router.post("", response_model=TutorOutput, status_code=status.HTTP_201_CREATED)
def create_tutor(data: TutorInput, connection: ConnectionDependency):
    """Cadastra um tutor."""
    return tutor_service.create_tutor(connection, data)


@router.get("", response_model=list[TutorOutput])
def list_tutors(connection: ConnectionDependency):
    """Lista os tutores."""
    return tutor_service.list_tutors(connection)


@router.get("/{tutor_id}", response_model=TutorOutput)
def get_tutor(tutor_id: int, connection: ConnectionDependency):
    """Consulta um tutor."""
    return tutor_service.get_tutor_or_raise(connection, tutor_id)


@router.put("/{tutor_id}", response_model=TutorOutput)
def replace_tutor(tutor_id: int, data: TutorInput, connection: ConnectionDependency):
    """Substitui os dados de um tutor."""
    return tutor_service.replace_tutor(connection, tutor_id, data)


@router.delete("/{tutor_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_tutor(tutor_id: int, connection: ConnectionDependency) -> Response:
    """Exclui um tutor sem pets."""
    tutor_service.delete_tutor(connection, tutor_id)
    return Response(status_code=status.HTTP_204_NO_CONTENT)


@router.get("/{tutor_id}/pets", response_model=list[PetOutput])
def list_pets_of_tutor(tutor_id: int, connection: ConnectionDependency):
    """Lista os pets de um tutor."""
    return tutor_service.list_pets_of_tutor(connection, tutor_id)


@router.get("/{tutor_id}/faturas", response_model=list[InvoiceOutput])
def list_invoices_of_tutor(tutor_id: int, connection: ConnectionDependency):
    """Lista as faturas de um tutor."""
    return tutor_service.list_invoices_of_tutor(connection, tutor_id)
"""Regras de negócio de veterinários."""

import sqlite3

from vetclinic.database import transaction
from vetclinic.errors import ResourceNotFoundError, StateConflictError
from vetclinic.repositories import Row
from vetclinic.repositories import veterinarios as veterinarian_repository
from vetclinic.schemas.veterinarios import VeterinarianInput

VETERINARIAN_NOT_FOUND_MESSAGE = "Veterinário não encontrado"
DUPLICATE_CRMV_MESSAGE = "Já existe um veterinário com este CRMV"


def get_veterinarian_or_raise(connection: sqlite3.Connection, veterinarian_id: int) -> Row:
    """Devolve o veterinário ou levanta `ResourceNotFoundError`."""
    veterinarian = veterinarian_repository.find_veterinarian_by_id(connection, veterinarian_id)
    if veterinarian is None:
        raise ResourceNotFoundError(VETERINARIAN_NOT_FOUND_MESSAGE)
    return veterinarian


def create_veterinarian(connection: sqlite3.Connection, data: VeterinarianInput) -> Row:
    """Cadastra um veterinário, garantindo CRMV único.

    A checagem e a inserção ocorrem na mesma transação; a restrição UNIQUE do banco
    continua sendo a garantia final contra corridas.
    """
    with transaction(connection):
        if veterinarian_repository.find_veterinarian_by_crmv(connection, data.crmv):
            raise StateConflictError(DUPLICATE_CRMV_MESSAGE)
        veterinarian_id = veterinarian_repository.insert_veterinarian(
            connection, data.nome, data.crmv
        )
    return get_veterinarian_or_raise(connection, veterinarian_id)


def list_veterinarians(connection: sqlite3.Connection) -> list[Row]:
    """Lista os veterinários."""
    return veterinarian_repository.list_veterinarians(connection)
"""Repositórios: único ponto de contato com o SQL; devolvem dicionários simples."""

import sqlite3
from typing import Any

Row = dict[str, Any]


def row_to_dict(row: sqlite3.Row | None) -> Row | None:
    """Converte uma linha do SQLite em dicionário, preservando `None` para 'não achado'."""
    return None if row is None else dict(row)
